'use strict';
function replyVoiceChoices(actor){const entries=[],seen=new Set();for(const s of project.scenes)for(const line of storyLines(s)){if(!line.speakerId||line.speakerId===actor.id||line.longVoiceGroupId&&line.longVoiceAnchorId!==line.id)continue;const speaker=s.objects.find(o=>o.id===line.speakerId),clip=tracks().find(c=>c.id===line.audioId);if(!speaker||!clip||speaker.name===actor.name)continue;const group=clip.longVoiceGroupId||clip.id;if(seen.has(group))continue;seen.add(group);entries.push({key:line.id,name:speaker.name+' · '+s.name+' · '+line.text.slice(0,45),lineId:line.id,voiceId:clip.id,groupId:clip.longVoiceGroupId||null})}for(const s of project.scenes)for(const speaker of storyActors(s)){const c=tracks().find(c=>c.id===speaker.speechTrackId);if(speaker.id===actor.id||speaker.name===actor.name||!c||seen.has(c.longVoiceGroupId||c.id))continue;entries.push({key:c.id,name:speaker.name+' · '+s.name,lineId:null,voiceId:c.id,groupId:c.longVoiceGroupId||null});seen.add(c.longVoiceGroupId||c.id)}return entries}
function replyStartsAfter(target,gap=0){const line=project.scenes.flatMap(storyLines).find(l=>l.id===target.lineId),clip=tracks().find(c=>c.id===(line?.audioId||target.voiceId));if(!clip)throw Error('That voice has changed. Choose who to follow again.');const clips=narrationGroupClips(clip);return Math.max(...clips.map(audioEnd))+clamp(gap,0,10)}
async function addCharacterReply(actor,target,text='',gap=0){if(actor.locked||window.editorTaskBusy||recording)throw Error('Choose an unlocked character after the current task finishes.');const at=replyStartsAfter(target,gap),original=project,copy=structuredClone(project);let total=totalDuration();if(at>=total-.1){if(copy.scenes.length>=99)throw Error('Add the reply in a new project, or make room in this project.');const previous=project.scenes.at(-1),built=withSceneTime(previous,previous.duration,()=>buildSceneContinuation(previous,{duration:Math.max(6,Math.ceil(at-total+6))}));copy.scenes.push(built.scene);total+=built.scene.duration}const {scene:s,offset}=narrationSceneAt(copy,at);if(storyLines(s).length>=200)throw Error('This scene has too many dialogue lines.');let speaking=s.objects.find(o=>o.id===actor.id||o.continuityId&&o.continuityId===actor.continuityId||isAnimatedCharacter(o)&&o.name===actor.name);if(!speaking){const source=project.scenes.find(s=>s.objects.some(o=>o.id===actor.id));speaking=continuitySnapshot(actor,source,Math.min(source.duration,clipEnd(actor,source)));s.objects.push(speaking)}if(speaking.locked)throw Error('Unlock the replying character in the target scene.');const line=makeStoryLine(text,speaking.id);line.start=line.manualStart=at-offset;line.pause=0;line.afterDialogue={...target,gap};(s.dialogue??=[]).push(line);if(!valid(copy))throw Error('This reply cannot fit the project safely.');Object.assign(project,copy);sceneIndex=project.scenes.findIndex(scene=>scene.id===s.id);time=line.start;selectLayers([speaking.id]);save();render();await openOfflineVoice(line);$('offlineVoiceDialog').querySelector('h2').textContent='Reply from '+speaking.name;$('addOfflineVoice').textContent='Add reply';return line}
const controlsBeforeEasyReplies=renderControls;renderControls=function(){controlsBeforeEasyReplies();const actor=object();if(!isAnimatedCharacter(actor))return;const panel=document.createElement('details');panel.innerHTML='<summary>Talk after another character</summary><select id="replyAfterCharacter" aria-label="Talk after"></select><label>Pause between voices (seconds)<input id="replyAfterGap" type="number" min="0" max="10" step="0.1" value="0"></label><textarea id="replyAfterText" rows="3" placeholder="Write this character’s reply."></textarea><button id="addReplyAfter">Create reply</button><p class="note">The reply starts when the selected character finishes speaking. Zero pause makes it immediate.</p>';const choices=replyVoiceChoices(actor),select=panel.querySelector('select');for(const item of choices){const option=document.createElement('option');option.value=item.key;option.textContent=item.name;select.append(option)}panel.querySelector('button').disabled=actor.locked||!choices.length;panel.querySelector('button').onclick=()=>{const target=choices.find(c=>c.key===select.value);if(target)addCharacterReply(actor,target,panel.querySelector('textarea').value,+panel.querySelector('input').value).catch(e=>toast(e.message))};($('controls').querySelector('[data-character-panel="voice"]')||$('controls')).append(panel)};
